<script setup lang="ts">
import OpeningCredit, {type OpeningCredit as CreditSource,type OpeningApplication} from './OpeningCredit.vue';
import {ref,computed,onMounted,watch} from 'vue';
import {supabase} from '@/lib/supabase';
import {useAuthStore} from '@/stores/auth';
import {useInvoicesStore} from '@/stores/invoices';
import {formatPen,penCents,penDecimal,limaDate} from '@/lib/financeMoney';
import type {Invoice} from '@/types/domain';
const props=defineProps<{zones:{id:string;name:string}[]}>();
const emit=defineEmits<{pay:[invoice:Invoice];changed:[];receipt:[id:string]}>();
type Cell={month:number;amount:string;paid:string;due:string;state:string;opening?:boolean;overdue:boolean;unreconciled:boolean;promotion:boolean};
type Row={id:string;client_id:string;customer:string;contract_number:string;client_code:string;service_type:string;plan:string;monthly_fee:string;status:string;technical_state:string;months:Cell[]};
type Matrix={rows:Row[];total:number;totals:{billed:string;paid:string;due:string;received:string};monthlyTotals:{month:number;amount:string;paid:string;due:string}[]};
type Payment={id:string;amount?:string;received?:string;applied?:string;credit_remaining?:string;method:string;reference:string;received_at:string;collector:string;reversed_at:string|null;reversal_reason:string;received_date_only?:boolean};
const auth=useAuthStore(),store=useInvoicesStore(),admin=computed(()=>['ADMIN','SUPERADMIN'].includes(auth.role??''));
const year=ref(Number(limaDate().slice(0,4))),zone=ref(''),search=ref(''),state=ref(''),page=ref(1),busy=ref(false),error=ref(''),message=ref(''),matrix=ref<Matrix|null>(null);
const labels:Record<string,string>={pagado:'Pagado',parcial:'Parcial',vencido:'Vencido',pendiente:'Pendiente',adelantado:'Adelantado',exonerado:'Exonerado',sin_facturacion:'Sin facturación'};
const months=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
const methods:Record<string,string>={cash:'Efectivo',yape:'Yape',plin:'Plin',transfer:'Transferencia',other:'Otros'};
async function rpc<T>(name:string,args:Record<string,unknown>):Promise<T>{const r=await supabase.rpc(name,args);if(r.error)throw Error(r.error.message);return r.data as T;}
const args=(n=page.value)=>({p_zone:zone.value,p_year:year.value,p_page:n,p_search:search.value.trim(),p_state:state.value});
async function load(reset=false){if(!zone.value){matrix.value=null;return;}if(reset)page.value=1;busy.value=true;error.value='';try{const requested=args();const data=await rpc<Matrix>('finance_pon_matrix',requested);if(JSON.stringify(requested)===JSON.stringify(args()))matrix.value=data;}catch(e){matrix.value=null;error.value=String(e);}finally{busy.value=false;}}
defineExpose({refresh:load});
onMounted(()=>{zone.value=props.zones[0]?.id??'';if(zone.value)void load();});
watch([zone,year,search,state],()=>{matrix.value=null;page.value=1;});
const openingCredits=ref<CreditSource[]>([]),openingApplications=ref<OpeningApplication[]>([]);
async function refreshOpening(){await openCell(current.value!,detailMonth.value);await load();emit('changed');}
const current=ref<Row|null>(null),detailMonth=ref(1),detail=ref<{invoices:Invoice[];payments:Payment[];adjustments:Record<string,unknown>[]} |null>(null),history=ref<Payment[]>([]),detailOpen=ref(false);
async function openCell(row:Row,month:number){current.value=row;detailMonth.value=month;detailOpen.value=true;detail.value=null;error.value='';try{const [d,h]=await Promise.all([rpc<NonNullable<typeof detail.value>>('finance_month_detail',{p_contract:row.id,p_year:year.value,p_month:month}),rpc<{payments:Payment[];openingCredits?:CreditSource[];openingApplications?:OpeningApplication[]}>('finance_history',{p_contract_id:row.id})]);detail.value=d;history.value=h.payments;openingCredits.value=h.openingCredits??[];openingApplications.value=h.openingApplications??[];}catch(e){error.value=String(e);}}
function pay(i:Invoice){detailOpen.value=false;emit('pay',{...i,service_contracts:{contract_number:current.value?.contract_number} as Invoice['service_contracts']});}
const action=ref(''),operationId=ref(''),reason=ref(''),amount=ref(''),source=ref<Payment|null>(null),options=ref<Invoice[]>([]),selected=ref<string[]>([]),method=ref('cash'),reference=ref('');
async function begin(kind:string,p?:Payment){action.value=kind;operationId.value=crypto.randomUUID();reason.value='';amount.value=kind==='fee'?String(current.value?.monthly_fee??''):String(p?.credit_remaining??'');source.value=p??null;selected.value=[];error.value='';method.value='cash';reference.value='';options.value=[];if(['advance','promo'].includes(kind)&&current.value){try{options.value=(await store.fetchInvoicesByContract(current.value.id)).filter(i=>i.status==='pending'&&i.finance_reconciled).sort((a,b)=>a.period_start.localeCompare(b.period_start));}catch(e){error.value=String(e);}}}
const promoTotal=computed(()=>{const selectedRows=options.value.filter(i=>selected.value.includes(i.id)).sort((a,b)=>a.period_start.localeCompare(b.period_start));return penDecimal(selectedRows.slice(0,3).reduce((n,i)=>n+penCents(i.amount_due),0));});
async function confirm(){if(busy.value||!current.value)return;error.value='';if(reason.value.trim().length<5){error.value='Indica un motivo de al menos cinco caracteres.';return;}busy.value=true;try{const common={p_operation_id:operationId.value,p_reason:reason.value.trim()};if(action.value==='reverse'){await rpc('finance_reverse_payment',{...common,p_payment_id:source.value?.id});}else if(action.value==='advance'){await rpc('finance_apply_advance',{...common,p_payment_id:source.value?.id,p_invoice_ids:selected.value,p_amount:penDecimal(penCents(amount.value))});}else if(action.value==='promo'){if(selected.value.length!==4)throw Error('Selecciona exactamente cuatro mensualidades consecutivas.');await rpc('finance_promo_3_1',{...common,p_contract_id:current.value.id,p_invoice_ids:selected.value,p_method:method.value,p_reference:reference.value||null});}else{await rpc('finance_set_monthly_fee',{...common,p_contract_id:current.value.id,p_amount:penDecimal(penCents(amount.value))});}action.value='';message.value='Operación financiera confirmada y auditada.';await load();current.value=matrix.value?.rows.find(r=>r.id===current.value?.id)??current.value;await openCell(current.value,detailMonth.value);emit('changed');}catch(e){error.value=String(e);}finally{busy.value=false;}}
const date=(value:string)=>new Date(value).toLocaleString('es-PE',{timeZone:'America/Lima'});
async function exportCsv(){if(!matrix.value||busy.value)return;busy.value=true;try{if(matrix.value.total>5000)throw Error('Acota la búsqueda a un máximo de 5000 contratos.');const parameters=args();const rows:Row[]=[];for(let n=1;n<=Math.ceil(matrix.value.total/25);n++)rows.push(...(await rpc<Matrix>('finance_pon_matrix',{...parameters,p_page:n})).rows);const header=['Cliente','Cintillo','Contrato','Servicio','Plan','Mensualidad PEN','Estado comercial','Estado técnico',...months.flatMap(m=>[m+' importe',m+' pagado',m+' saldo',m+' estado'])];const safe=(v:unknown)=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const data=rows.map(r=>[r.customer,r.client_code,r.contract_number,r.service_type,r.plan,r.monthly_fee,r.status,'Sin verificar',...r.months.flatMap(c=>[c.amount,c.paid,c.due,labels[c.state]])]);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+[header,...data].map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.download=`cobranza-pon-${year.value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(e){error.value=String(e);}finally{busy.value=false;}}
</script>
<template>
 <section class="pon-workspace"><div class="finance-table-tools"><h2>Cobranza por PON</h2><button class="btn-ghost" :disabled="busy||!matrix" @click="exportCsv">Exportar PON a Excel (CSV)</button></div>
 <form class="finance-filters" @submit.prevent="load(true)"><label>PON / zona<select v-model="zone" aria-label="PON de cobranza"><option value="">Seleccionar zona</option><option v-for="z in zones" :key="z.id" :value="z.id">{{z.name}}</option></select></label><label>Año<input v-model.number="year" type="number" min="2020" max="2100" aria-label="Año de matriz"></label><label>Buscar<input v-model="search" maxlength="100" placeholder="Cliente, DNI, contrato o cintillo" aria-label="Buscar en PON"></label><label>Estado financiero<select v-model="state"><option value="">Todos</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><button class="btn-secondary" :disabled="busy">{{busy?'Consultando…':'Actualizar matriz'}}</button></form>
 <p class="finance-help">Mensualidades por inicio de período · saldos actuales · una fila por contrato. Una celda sin facturación no acredita deuda. El estado técnico se verifica por separado.</p>
 <p v-if="error" role="alert" class="finance-error">{{error}}</p><p v-if="message" role="status" class="finance-notice">{{message}}</p>
 <template v-if="matrix"><div class="pon-totals"><span>Emitido <b>{{formatPen(matrix.totals.billed)}}</b></span><span>Aplicado a mensualidades <b>{{formatPen(matrix.totals.paid)}}</b></span><span>Saldo <b>{{formatPen(matrix.totals.due)}}</b></span><span>Caja neta del año <b>{{formatPen(matrix.totals.received)}}</b></span></div>
 <div class="pon-legend"><span v-for="(label,key) in labels" :key="key" :class="['pon-state',key]">{{label}}</span></div>
 <div class="pon-scroll" tabindex="0" aria-label="Matriz anual de cobranza"><table class="pon-matrix"><thead><tr><th class="pon-name">Cliente / cintillo</th><th class="pon-contract">Contrato / servicio</th><th v-for="m in months" :key="m">{{m}}</th></tr></thead><tbody><tr v-for="r in matrix.rows" :key="r.id"><th class="pon-name">{{r.customer}}<small>{{r.client_code||'Sin cintillo'}}</small></th><th class="pon-contract">{{r.contract_number}}<small>{{r.plan}} · {{formatPen(r.monthly_fee)}}</small><small>{{r.service_type==='solo_iptv'?'IPTV':'Paquete Internet'}} · Comercial: {{r.status}}</small><small>Técnico: sin verificar</small></th><td v-for="c in r.months" :key="c.month"><button :class="['pon-cell',c.state]" @click="openCell(r,c.month)"><span>{{c.state==='sin_facturacion'?'—':formatPen(c.due==='0.00'||Number(c.due)===0?c.amount:c.due)}}</span><small>{{labels[c.state]}}{{c.overdue&&c.state==='parcial'?' / vencido':''}}{{c.promotion?' · 3+1':''}}</small><small v-if="c.opening">Saldo inicial conciliado</small><small v-if="c.unreconciled">No conciliada</small></button></td></tr><tr v-if="!matrix.rows.length"><td colspan="14">Sin contratos para estos filtros.</td></tr></tbody><tfoot><tr><th class="pon-name">Saldo total PON</th><th class="pon-contract">{{matrix.total}} contratos filtrados</th><td v-for="m in matrix.monthlyTotals" :key="m.month">{{formatPen(m.due)}}</td></tr></tfoot></table></div>
 <div class="finance-pagination"><span>{{matrix.total}} contratos · página {{page}} · 25 filas</span><button :disabled="busy||page===1" @click="page--;load()">Anterior</button><button :disabled="busy||page*25>=matrix.total" @click="page++;load()">Siguiente</button></div></template>
 <p v-else-if="!busy" class="finance-empty">Selecciona una PON/zona real para consultar sus contratos.</p>
 </section>
 <Teleport to="body"><div v-if="detailOpen" class="modal-overlay"><section class="modal-panel finance-dialog" role="dialog" aria-modal="true"><div class="finance-dialog-head"><h2>{{current?.contract_number}} · {{months[detailMonth-1]}} {{year}}</h2><button aria-label="Cerrar mensualidad" :disabled="busy" @click="detailOpen=false;action=''">×</button></div><p>{{current?.customer}} · {{current?.client_code}} · {{current?.plan}}</p><p class="finance-help">Comercial: {{current?.status}} · Técnico: sin verificar. Ninguna operación financiera ejecuta acciones de red.</p>
 <p v-if="error" role="alert" class="finance-error">{{error}}</p><p v-if="!detail">Cargando mensualidad…</p><template v-else><p v-if="!detail.invoices.length">Sin facturación en este mes. No se presume deuda.</p><div v-for="i in detail.invoices" :key="i.id" class="finance-history-line"><b>{{i.invoice_number}}</b> · {{i.period_start}}<p>Emitido {{formatPen(i.amount)}} · Pagado {{formatPen(i.amount_paid)}} · Saldo {{formatPen(i.amount_due)}}</p><button v-if="i.status==='pending'" class="btn-primary" @click="pay(i)">Registrar pago</button><small v-if="!i.finance_reconciled">No conciliada: cobro bloqueado por el servidor.</small></div>
 <h3>Movimientos de la mensualidad</h3><p v-for="(p,n) in detail.payments" :key="p.id+'-'+n" class="finance-history-line">{{p.received_date_only?new Date(p.received_at).toLocaleDateString('es-PE',{timeZone:'America/Lima'}):date(p.received_at)}} · Aplicado {{formatPen(p.applied)}} · {{methods[p.method]}} · {{p.reference||'Sin referencia'}}<button class="finance-link" @click="emit('receipt',p.id)">Ver / descargar recibo</button><small>{{p.collector}} · {{p.reversed_at?'REVERSADO: '+p.reversal_reason:'Vigente'}}</small></p><p v-for="(a,n) in detail.adjustments" :key="n">{{a.tipo}} · {{formatPen(String(a.monto))}} · {{a.reversed_at?'Revertido':'Sin ingreso de caja'}}</p>
 <OpeningCredit :credits="openingCredits" :applications="openingApplications" :invoices="detail.invoices" :admin="admin" @changed="refreshOpening"/><h3>Historial de pagos del contrato</h3><div v-for="p in history" :key="p.id" class="finance-history-line">{{p.received_date_only?new Date(p.received_at).toLocaleDateString('es-PE',{timeZone:'America/Lima'}):date(p.received_at)}} · {{formatPen(p.amount)}} · {{methods[p.method]}}<small>{{p.collector}} · {{p.reference}} · {{p.reversed_at?'Reversado':'Vigente'}}</small><button v-if="admin&&!p.reversed_at" class="finance-link danger" @click="begin('reverse',p)">Reversar pago</button><button v-if="!p.reversed_at&&Number(p.credit_remaining)>0" class="finance-link" @click="begin('advance',p)">Aplicar anticipo {{formatPen(p.credit_remaining)}}</button></div><p class="finance-help">Hasta 100 pagos. Cada reverso conserva el movimiento original y requiere motivo.</p>
 <div v-if="admin" class="finance-shortcuts"><button @click="begin('fee')">Mensualidad personalizada</button><button @click="begin('promo')">Preparar promoción 3+1</button></div>
 <form v-if="action" class="pon-operation" @submit.prevent="confirm"><h3>{{({reverse:'Confirmar reversión',advance:'Aplicar saldo adelantado',promo:'Tres meses pagados + cuarto gratis',fee:'Mensualidad futura personalizada'} as Record<string,string>)[action]}}</h3><p v-if="action==='reverse'">Se reversará el pago completo de {{formatPen(source?.amount)}}. No se borra su historial.</p><p v-if="action==='promo'">Selecciona cuatro facturas mensuales futuras, consecutivas y del mismo importe. Cobro: {{formatPen(promoTotal)}}; el cuarto mes es una promoción sin dinero recibido. Reglas conservadoras pendientes de validación comercial.</p><div v-if="action==='advance'||action==='promo'" class="finance-invoice-options"><label v-for="i in options" :key="i.id"><input v-model="selected" type="checkbox" :value="i.id"><span>{{i.period_start}} · {{i.invoice_number}}</span><b>{{formatPen(i.amount_due)}}</b></label></div><div class="finance-form-grid"><label v-if="action==='advance'||action==='fee'">Importe PEN<input v-model="amount" inputmode="decimal" required></label><template v-if="action==='promo'"><label>Método<select v-model="method"><option v-for="(label,key) in methods" :key="key" :value="key">{{label}}</option></select></label><label>Número de operación<input v-model="reference" maxlength="100"></label></template><label>Motivo<input v-model="reason" required minlength="5" maxlength="500"></label></div><p v-if="error" role="alert" class="finance-error">{{error}}</p><div class="finance-dialog-actions"><button type="button" class="btn-ghost" :disabled="busy" @click="action=''">Cancelar</button><button class="btn-primary" :disabled="busy">Confirmar operación auditada</button></div></form></template></section></div></Teleport>
</template>
<style scoped>
.pon-workspace{min-width:0}.pon-totals{display:flex;flex-wrap:wrap;gap:12px 30px;padding:12px 0;font-size:12px}.pon-totals b{display:block;font-size:17px;font-variant-numeric:tabular-nums}.pon-legend{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 12px}.pon-state{font-size:10px;padding:3px 7px;border-radius:4px}.pon-scroll{max-height:64vh;overflow:auto;border:1px solid var(--border-color,#dde4eb);border-radius:6px;isolation:isolate}.pon-matrix{border-collapse:separate;border-spacing:0;width:max-content;min-width:100%;font-size:11px}.pon-matrix th,.pon-matrix td{padding:6px;border-bottom:1px solid #e5eaf0;border-right:1px solid #edf0f4;background:var(--bg-card,#fff);vertical-align:middle}.pon-matrix thead th{position:sticky;top:0;z-index:3;background:var(--bg-secondary,#f3f6fa);height:35px}.pon-name{position:sticky;left:0;width:165px;min-width:165px;max-width:165px;text-align:left;z-index:2}.pon-contract{position:sticky;left:165px;width:210px;min-width:210px;max-width:210px;text-align:left;z-index:2;box-shadow:2px 0 4px #00000009}.pon-matrix thead .pon-name,.pon-matrix thead .pon-contract{z-index:4}.pon-matrix small{display:block;font-size:10px;font-weight:400;margin-top:3px;white-space:normal}.pon-cell{width:104px;min-height:53px;padding:6px;border:1px solid transparent;border-radius:4px;text-align:right;cursor:pointer;font-variant-numeric:tabular-nums}.pon-cell:hover{border-color:#597f9c}.pagado{background:#eaf3ed;color:#246241}.adelantado{background:#e9f0f9;color:#315b87}.parcial{background:#fff3db;color:#865a12}.vencido{background:#f9eaea;color:#9c4141}.pendiente{background:#eef1f5;color:#4b5d73}.exonerado{background:#f0ecf8;color:#69558c}.sin_facturacion{background:#f7f8fa;color:#8691a0}.pon-matrix tfoot th,.pon-matrix tfoot td{position:sticky;bottom:0;background:var(--bg-secondary,#f3f6fa);font-weight:600;z-index:3}.pon-matrix tfoot .pon-name,.pon-matrix tfoot .pon-contract{z-index:4}.pon-operation{margin-top:16px;padding:14px;border:1px solid #cad7e1;border-radius:6px}@media(max-width:600px){.pon-name{width:115px;min-width:115px;max-width:115px}.pon-contract{left:115px;width:155px;min-width:155px;max-width:155px}.pon-scroll{max-height:58vh}.pon-cell{width:95px}.pon-totals{gap:10px 20px}}
</style>
